import type { Models } from "@earendil-works/pi-ai/models";
import type { Extension } from "@earendil-works/pi-durable";

import { Activity, formatStats, oneLine } from "./activity.ts";
import {
	buildPrompt,
	formatFollowUp,
	type PIContext,
	withReplyReminder,
} from "./context.ts";
import { ThreadConversation, type ThreadResult } from "./conversation.ts";
import { createDurableExtensions } from "./durable-extensions.ts";
import { loadExtensions } from "./extensions.ts";
import {
	formatErrorComment,
	formatSuccessComment,
	formatThreadLog,
	formatThreadSummary,
} from "./formatting.ts";
import { createGitHubUi, type GitHubUi } from "./github-ui.ts";
import {
	type GitHubClient,
	isForkPullRequest,
	type ReactionTarget,
} from "./github.ts";
import type { ActionInputs } from "./inputs.ts";
import { createActionModels, findModel } from "./models.ts";
import { getRunContext } from "./run-context.ts";
import { GitSyncConflictError } from "./storage/sync.ts";
import type { SnapshotLimits } from "./storage/worktree.ts";
import { Thread } from "./thread.ts";
import { toolEnv } from "./tool-env.ts";
import { collectTriggers, type Trigger, triggerFromInfo } from "./triggers.ts";
import type { Log, TriggerInfo } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type Env = Record<string, string | undefined>;

export interface Logger extends Log {
	debug: (msg: string) => void;
	error: (msg: string) => void;
	setFailed: (msg: string) => void;
	setOutput: (name: string, value: string) => void;
	startGroup: (name: string) => void;
	endGroup: () => void;
}

export interface ActionDependencies {
	inputs: ActionInputs;
	/** The webhook payload of the event that started the workflow. */
	payload: Record<string, unknown>;
	createClient: (token: string) => GitHubClient;
	log: Logger;
	cwd: string;
	/** Override model setup (tests use a faux provider). */
	createModels?: ((inputs: ActionInputs) => Promise<Models>) | undefined;
	/** Git remote holding the thread refs. Default "origin". */
	remote?: string;
	env?: Env;
	/** Appends Markdown to the job summary (notifications from pi-durable extensions). */
	summary?: (markdown: string) => Promise<void>;
}

/**
 * The `extensions` input and the model setup: the built-in and custom providers and those extensions register
 * (unless `createModels` overrides it), the pi-durable extensions for the thread, which get the GitHub UI when
 * the run posts to an issue or PR, and the variables the agent's tools get (see `toolEnv()`). pi-durable extensions
 * run in this process, so when there are any, those variables are set in its environment too (after npm ran).
 */
async function setUp(
	deps: ActionDependencies,
	gh: GitHubClient,
	issueNumber: number | undefined,
): Promise<{
	models: Models;
	extensions: Extension[];
	tools: Record<string, string>;
	ui: GitHubUi | undefined;
}> {
	const { inputs, log, cwd } = deps;
	const env = deps.env ?? process.env;
	const loaded = await loadExtensions({
		specs: inputs.extensions,
		cwd,
		log,
		env,
	});
	const models = deps.createModels
		? await deps.createModels(inputs)
		: await createActionModels(inputs, {
				providers: loaded.providers,
				env,
				log,
			});
	const tools = await toolEnv({ token: inputs.githubToken, cwd, env });
	if (Object.keys(tools).length > 0) {
		log.info(`The agent's tools get ${Object.keys(tools).join(", ")}`);
	}
	if (loaded.durable.length > 0) {
		Object.assign(env, tools);
	}
	const ui =
		inputs.outputMode === "comment" && issueNumber !== undefined
			? createGitHubUi({ gh, issueNumber, log, summary: deps.summary })
			: undefined;
	const extensions = await createDurableExtensions(loaded.durable, {
		cwd,
		agentDir: inputs.agentDir,
		trustProject: inputs.trustProject,
		ui,
		log,
		env,
	});
	return { models, extensions, tools, ui };
}

/** On cancellation (SIGINT, then SIGTERM), push what the thread has so far before the runner kills us. */
function pushOnSignals(thread: Thread, log: Log): () => void {
	const handler = (signal: NodeJS.Signals) => {
		log.warning(`Received ${signal}; saving the thread before exiting`);
		thread
			.push()
			.catch((error: unknown) => {
				log.warning(getErrorMessage(error));
			})
			.finally(() => {
				process.exitCode = 1;
				process.kill(process.pid, "SIGKILL");
			})
			.catch(() => undefined);
	};
	process.once("SIGINT", handler);
	process.once("SIGTERM", handler);
	return () => {
		process.off("SIGINT", handler);
		process.off("SIGTERM", handler);
	};
}

/** One line for the model and the pi-durable extensions, after the setup group. */
function describeSetup(
	inputs: ActionInputs,
	extensions: readonly Extension[],
): string {
	const loaded = extensions.map(
		(extension) =>
			`${extension.name} (${(extension.tools ?? []).map((tool) => tool.name).join(", ") || "no tools"})`,
	);
	return `🤖 ${inputs.provider}/${inputs.model}${loaded.length > 0 ? ` · extensions: ${loaded.join(", ")}` : ""}`;
}

/** One line for a request as pi gets it: who, where, and its first line. */
function describeTrigger(trigger: Trigger): string {
	const what = trigger.answer ? "Answer" : "Request";
	const where = trigger.url ? ` (${trigger.url})` : "";
	return `▶ ${what} from @${trigger.author.login}${where}: ${oneLine(trigger.task || trigger.text)}`;
}

/** The context of the first message of a thread, for the trigger that starts it. */
function contextFor(piContext: PIContext, trigger: Trigger): PIContext {
	return piContext.type === "direct"
		? piContext
		: { ...piContext, task: trigger.task, triggerComment: trigger.text };
}

/** A run from workflow_dispatch or a direct prompt: one request, keyed by the workflow run. */
function oneOffTrigger(piContext: PIContext, env: Env): Trigger {
	const runId = env["GITHUB_RUN_ID"] ?? String(Date.now());
	const attempt = env["GITHUB_RUN_ATTEMPT"] ?? "1";
	return {
		key: `run-${runId}-${attempt}`,
		source: "body",
		issueNumber: piContext.type === "direct" ? 0 : piContext.number,
		author: { login: env["GITHUB_ACTOR"] ?? "workflow", type: "User" },
		text: piContext.task,
		task: piContext.task,
		createdAt: new Date().toISOString(),
	};
}

/** What the run starts with: every unanswered trigger on the thread in comment mode, else one request. */
async function initialTriggers(
	deps: ActionDependencies,
	gh: GitHubClient,
	piContext: PIContext,
	triggerInfo: TriggerInfo | undefined,
	since: Date | undefined,
	answer: Trigger | undefined,
): Promise<Trigger[]> {
	const { inputs } = deps;
	if (!triggerInfo) {
		return [oneOffTrigger(piContext, deps.env ?? process.env)];
	}
	const current = answer ?? triggerFromInfo(triggerInfo, inputs.triggerPhrase);
	return inputs.outputMode === "comment"
		? collectTriggers(gh, triggerInfo, inputs, since, current)
		: [current];
}

/** The working-tree snapshot limits of the thread; undefined (off) by input and on fork pull requests. */
function worktreeLimits(deps: ActionDependencies): SnapshotLimits | undefined {
	const { inputs, log } = deps;
	if (!inputs.worktreeSnapshots) {
		return undefined;
	}
	if (isForkPullRequest(deps.payload)) {
		log.info(
			"A pull request from a fork: its token can't push, so the working tree is not saved",
		);
		return undefined;
	}
	return inputs.worktreeLimits;
}

/** Close the thread, pushing it; a failure to save is a warning, not a failed run. */
async function closeThread(thread: Thread, log: Log): Promise<void> {
	try {
		await thread.close();
	} catch (error) {
		log.warning(
			error instanceof GitSyncConflictError
				? `${thread.ref} moved on the remote while this run worked; its history was not pushed. ${getErrorMessage(error)}`
				: `Could not save the thread: ${getErrorMessage(error)}`,
		);
	}
}

/** The thread, first thing in the log: whether it is new, with how to read it with git in its group. */
function announceThread(deps: ActionDependencies, thread: Thread): void {
	const { log } = deps;
	if (thread.ref === undefined) {
		log.info("🧵 One-off conversation (not stored)");
		return;
	}
	const since = thread.startedAt
		?.toISOString()
		.replace(/:\d\d\.\d+Z$/u, " UTC");
	log.startGroup(
		`🧵 Thread ${thread.ref}: ${since === undefined ? "new" : `continuing, started ${since.replace("T", " ")}`}`,
	);
	log.info(formatThreadLog(thread.ref, deps.remote ?? "origin"));
	log.endGroup();
}

/** After the final push: where the thread is now, in the log, and how to read it, in the job summary. */
async function showThread(
	deps: ActionDependencies,
	thread: Thread,
	ref: string,
): Promise<void> {
	const { log } = deps;
	const remote = deps.remote ?? "origin";
	const { tip } = thread;
	log.info(
		`🧵 ${ref} is at ${tip === undefined ? "(nothing stored)" : tip.slice(0, 7)}`,
	);
	try {
		await deps.summary?.(formatThreadSummary(ref, remote));
	} catch (error) {
		log.warning(`Could not write the job summary: ${getErrorMessage(error)}`);
	}
}

export async function run(deps: ActionDependencies): Promise<void> {
	const resolved = await getRunContext(deps);
	if (!resolved) {
		return;
	}
	const { piContext, ghClient: gh, triggerInfo } = resolved;
	const { inputs, log } = deps;
	const activity = new Activity(log);
	const issueNumber =
		piContext.type === "direct" ? undefined : piContext.number;
	// In comment mode, a trigger makes the run a conversation on its issue or PR (reactions, new comments join).
	const interactive = inputs.outputMode === "comment" ? triggerInfo : undefined;

	/** Set the outputs, or react on `target` and post the result unless it was posted before. Returns where it went. */
	const report = async (
		result: ThreadResult,
		target: ReactionTarget | undefined,
		ref?: string,
		alreadyPosted = false,
	): Promise<string | undefined> => {
		if (!result.success) {
			log.error(`pi execution failed: ${result.error}`);
		}
		const stats = formatStats(activity.take());
		if (inputs.outputMode === "output") {
			log.info(`${result.success ? "✅" : "❌"} Set the outputs (${stats})`);
			log.setOutput("success", String(result.success));
			log.setOutput(
				"response",
				result.success ? result.response : result.error,
			);
			return "output";
		}
		if (target) {
			await gh.addReaction(target, result.success ? "rocket" : "confused");
		}
		if (alreadyPosted || issueNumber === undefined) {
			return undefined;
		}
		const body = result.success
			? formatSuccessComment(result.response, ref)
			: formatErrorComment(result.error, ref);
		const { url } = await gh.createComment(issueNumber, body);
		log.info(
			`${result.success ? "✅ Replied" : "❌ Reported the error"}: ${url} (${stats})`,
		);
		return url;
	};

	if (interactive) {
		await gh.addReaction(interactive, "eyes");
	}
	let thread: Thread | undefined;
	let stopSignals: (() => void) | undefined;
	try {
		log.startGroup("Setup");
		let setup: Awaited<ReturnType<typeof setUp>>;
		try {
			setup = await setUp(deps, gh, issueNumber);
		} finally {
			log.endGroup();
		}
		const { models, extensions, tools, ui } = setup;
		log.info(describeSetup(inputs, extensions));
		const opened = await Thread.open({
			cwd: deps.cwd,
			issueNumber,
			models,
			model: findModel(models, inputs.provider, inputs.model),
			log,
			remote: deps.remote,
			extensions,
			toolEnv: tools,
			worktree: worktreeLimits(deps),
			onEntries: (entries) => {
				activity.entries(entries);
			},
		});
		thread = opened;
		stopSignals = pushOnSignals(opened, log);
		announceThread(deps, opened);
		// New comments: on a new thread, from the time of the trigger; on an existing one, since it began.
		const since =
			opened.startedAt ??
			new Date(
				Date.parse(interactive?.createdAt ?? new Date().toISOString()) - 1000,
			);
		const conversation = new ThreadConversation({
			thread: opened,
			log,
			timeoutSeconds: inputs.timeout,
			pollIntervalMs: inputs.pollInterval * 1000,
			message: async (trigger, first) => {
				// As `report` does, pi-action posts the reply: say so, or pi may post it with `gh` too (#42).
				const repliesAsComment =
					inputs.outputMode === "comment" && issueNumber !== undefined;
				if (first && !trigger.answer) {
					return buildPrompt(
						contextFor(piContext, trigger),
						inputs.promptTemplate,
						{ repliesAsComment },
					);
				}
				const message = trigger.answer ? trigger.text : formatFollowUp(trigger);
				return repliesAsComment ? withReplyReminder(message) : message;
			},
			started: (trigger) => {
				log.info(describeTrigger(trigger));
			},
			deliver: async (trigger, result, alreadyPosted) =>
				report(
					result,
					interactive ? trigger : undefined,
					opened.ref,
					alreadyPosted,
				),
			...(interactive
				? { poll: async () => collectTriggers(gh, interactive, inputs, since) }
				: {}),
			...(ui ? { asked: () => ui.asked } : {}),
		});
		await conversation.run(
			await initialTriggers(
				deps,
				gh,
				piContext,
				triggerInfo,
				opened.startedAt,
				resolved.answer,
			),
		);
		if (conversation.failures.length > 0) {
			log.setFailed(
				`pi could not answer ${conversation.failures.length} comment(s): ${conversation.failures.join("; ")}`,
			);
		}
	} catch (error) {
		await report(
			{ success: false, error: getErrorMessage(error) },
			interactive,
		);
	} finally {
		stopSignals?.();
		if (thread) {
			await closeThread(thread, log);
			if (thread.ref !== undefined) {
				await showThread(deps, thread, thread.ref);
			}
		}
	}
}
import type { Trigger } from "./triggers.ts";

export function hasTrigger(text: string, trigger: string): boolean {
	return text.toLowerCase().includes(trigger.toLowerCase());
}

/** Appended to every first prompt: the runner, and anything left uncommitted on it, is gone after the run. */
const RUNNER_REQUIREMENTS = `## Important: Artifact and Script Requirements

**CRITICAL:** After the GitHub Action finishes running, all files modified or created are lost, and the GitHub Action runner is destroyed. Therefore:

1. **All generated code and artifacts MUST be committed** - Any files you create, modify, or generate must be committed and pushed to the repository before the action completes. Nothing will persist otherwise.

2. **Any throw-away scripts generated MUST be run immediately** - If you create temporary scripts (like \`/tmp/create-issues.sh\` or similar), you must execute them during the same session. They will be lost when the runner terminates.

3. **Commit and push all work** - Always end your work by committing and pushing changes to ensure they persist beyond the GitHub Action execution.
`;

/**
 * In comment mode, pi-action posts the final response of each request as a comment. pi's tools have a token that
 * can comment too, and without this it may post its reply with `gh` as well: two comments for one answer (#42).
 */
const REPLY_SECTION = `## Your Reply

pi-action posts your final response as a comment on this issue or pull request. **Do not post your reply yourself**, for example with \`gh issue comment\`, \`gh pr comment\`, \`gh pr review\`, or \`gh api\`. That would post the same answer twice. Use \`gh\` to comment only where the task asks for it, such as on another issue.
`;

/** Appended to each later message (a follow-up or an answer) in comment mode, for threads of any age. */
export const REPLY_REMINDER =
	"_(pi-action posts your final response as a comment here. Don't also post it with `gh`.)_";

/** A later message on the thread, with the reminder that pi-action posts the reply. */
export function withReplyReminder(message: string): string {
	return `${message}\n\n${REPLY_REMINDER}`;
}

export function extractTask(comment: string, trigger: string): string {
	const idx = comment.toLowerCase().indexOf(trigger.toLowerCase());
	if (idx === -1) {
		return comment;
	}
	return comment.slice(idx + trigger.length).trim();
}

interface BasePIContext {
	type: "issue" | "pull_request" | "direct";
	title: string;
	task: string;
}

interface IssuePIContext extends BasePIContext {
	type: "issue";
	body: string;
	number: number;
	triggerComment: string;
}

interface PullRequestPIContext extends BasePIContext {
	type: "pull_request";
	body: string;
	number: number;
	triggerComment: string;
	diff?: string;
	reviewComments?: string;
}

interface DirectPIContext extends BasePIContext {
	type: "direct";
}

export type PIContext = IssuePIContext | PullRequestPIContext | DirectPIContext;

const PLACEHOLDER_PATTERN = /\{\{(\w+)\}\}/gu;

const TYPE_DISPLAY: Record<PIContext["type"], string> = {
	issue: "Issue",
	pull_request: "Pull Request",
	direct: "Direct Task",
};

export function renderTemplate(template: string, context: PIContext): string {
	const isDirect = context.type === "direct";
	const variables = new Map(
		Object.entries({
			type: context.type,
			type_display: TYPE_DISPLAY[context.type],
			number: isDirect ? "0" : context.number.toString(),
			title: context.title,
			body: isDirect ? "" : context.body,
			task: context.task,
			diff: context.type === "pull_request" ? (context.diff ?? "") : "",
			reviewComments:
				context.type === "pull_request" ? (context.reviewComments ?? "") : "",
			trigger_comment: isDirect ? context.task : context.triggerComment,
		}),
	);
	// One pass with a replacer: values go in literally ("$&" stays "$&"), and a placeholder inside a value (an
	// issue body that says {{diff}}) stays text instead of being expanded.
	return template.replaceAll(
		PLACEHOLDER_PATTERN,
		(placeholder, key: string) => variables.get(key) ?? placeholder,
	);
}

export interface PromptOptions {
	/** pi-action posts the final response as a comment (comment mode, on an issue or PR). */
	repliesAsComment?: boolean;
}

export function buildPrompt(
	context: PIContext,
	customTemplate?: string,
	options: PromptOptions = {},
): string {
	if (customTemplate?.trim()) {
		return renderTemplate(customTemplate, context);
	}

	if (context.type === "direct") {
		return `# Direct pi Task

## Task
${context.task}

${RUNNER_REQUIREMENTS}`;
	}

	let prompt = `# GitHub ${TYPE_DISPLAY[context.type]} #${context.number}

## Title
${context.title}

## Description
${context.body}

${context.type === "pull_request" ? (context.reviewComments ?? "") : ""}
## Task
${context.task}

${options.repliesAsComment === true ? `${REPLY_SECTION}\n` : ""}${RUNNER_REQUIREMENTS}`;

	if (context.type === "pull_request" && context.diff) {
		prompt += `\n## PR Diff\n\`\`\`diff\n${context.diff}\n\`\`\`\n`;
	}

	return prompt;
}

/** A later comment on an existing thread: the conversation already has the issue's context. */
export function formatFollowUp(
	trigger: Pick<Trigger, "author" | "source" | "task" | "url">,
): string {
	const verb =
		trigger.source === "review_comment" ? "commented on the diff" : "commented";
	const where = trigger.url ? ` (${trigger.url})` : "";
	return `**@${trigger.author.login}** ${verb}${where}:\n\n${trigger.task}`;
}
import { extractTask, hasTrigger } from "./context.ts";
import { isQuestionComment } from "./github-ui.ts";
import { type GitHubClient, toUserType } from "./github.ts";
import {
	type Allowlists,
	sanitizeInput,
	validatePermissions,
} from "./security.ts";
import type {
	GitHubComment,
	GitHubUser,
	TriggerInfo,
	TriggerSource,
	UiAnswer,
} from "./types.ts";

/** One request for pi: an issue/PR body or comment that mentions the trigger phrase. */
export interface Trigger {
	/** Stable per GitHub item; used as the submission's requestId so it is answered once. */
	key: string;
	source: TriggerSource;
	issueNumber: number;
	commentId?: number;
	author: GitHubUser;
	/** The sanitized text, and the task: what follows the trigger phrase. */
	text: string;
	task: string;
	createdAt: string;
	url?: string;
	/** Set when this is the answer to a question from a pi-durable extension; `text` is the message for the model. */
	answer?: UiAnswer;
}

/** Who may run pi, and how they ask: the trigger_phrase and allowed_* inputs. */
export interface TriggerFilter extends Allowlists {
	triggerPhrase: string;
}

export function triggerKey(
	source: TriggerSource,
	issueNumber: number,
	commentId?: number,
): string {
	if (source === "body" || commentId === undefined) {
		return `issue-${issueNumber}`;
	}
	return source === "review_comment"
		? `review-comment-${commentId}`
		: `comment-${commentId}`;
}

function toTrigger(
	item: Omit<Trigger, "key" | "text" | "task">,
	rawText: string,
	triggerPhrase: string,
): Trigger {
	const text = sanitizeInput(rawText);
	return {
		key: triggerKey(item.source, item.issueNumber, item.commentId),
		...item,
		text,
		task: extractTask(text, triggerPhrase),
	};
}

export function triggerFromInfo(
	info: TriggerInfo,
	triggerPhrase: string,
): Trigger {
	return toTrigger(
		{
			source: info.source,
			issueNumber: info.issueNumber,
			...(info.commentId === undefined ? {} : { commentId: info.commentId }),
			author: info.author,
			createdAt: info.createdAt ?? new Date().toISOString(),
			...(info.url ? { url: info.url } : {}),
		},
		info.triggerText,
		triggerPhrase,
	);
}

/**
 * The comments that mention the trigger phrase and whose authors may run pi. Questions from extensions and their
 * `/answer` replies are never triggers, even when they mention the phrase.
 */
export function triggersFromComments(
	comments: GitHubComment[],
	source: Exclude<TriggerSource, "body">,
	issueNumber: number,
	filter: TriggerFilter,
): Trigger[] {
	return comments.flatMap(
		({ id, body, user, author_association, created_at, html_url }) => {
			const text = body ?? "";
			if (
				!(user && hasTrigger(text, filter.triggerPhrase)) ||
				isQuestionComment(text)
			) {
				return [];
			}
			const author: GitHubUser = {
				login: user.login,
				type: toUserType(user.type),
			};
			if (!validatePermissions(author, author_association, filter)) {
				return [];
			}
			const item = {
				source,
				issueNumber,
				commentId: id,
				author,
				createdAt: created_at,
				url: html_url,
			};
			return [toTrigger(item, body ?? "", filter.triggerPhrase)];
		},
	);
}

async function triggersSince(
	client: GitHubClient,
	info: Pick<TriggerInfo, "issueNumber" | "isPullRequest">,
	filter: TriggerFilter,
	since: Date,
): Promise<Trigger[]> {
	const iso = since.toISOString();
	const comments = await client.listIssueComments(info.issueNumber, iso);
	const found = triggersFromComments(
		comments,
		"comment",
		info.issueNumber,
		filter,
	);
	if (info.isPullRequest) {
		const reviews = await client.listReviewComments(info.issueNumber, iso);
		found.push(
			...triggersFromComments(
				reviews,
				"review_comment",
				info.issueNumber,
				filter,
			),
		);
	}
	// `since` filters by update time; keep only comments created since.
	return found.filter(
		(trigger) => Date.parse(trigger.createdAt) >= since.getTime(),
	);
}

/**
 * Every trigger on the thread created after `since` (comments a cancelled or still-pending run never handled,
 * and ones posted while this run works), plus `current`, oldest first and without duplicates.
 */
export async function collectTriggers(
	client: GitHubClient,
	info: Pick<TriggerInfo, "issueNumber" | "isPullRequest">,
	filter: TriggerFilter,
	since: Date | undefined,
	current?: Trigger,
): Promise<Trigger[]> {
	const found = since ? await triggersSince(client, info, filter, since) : [];
	const byKey = new Map<string, Trigger>();
	for (const trigger of current ? [current, ...found] : found) {
		if (!byKey.has(trigger.key)) {
			byKey.set(trigger.key, trigger);
		}
	}
	return [...byKey.values()].toSorted(
		(a, b) => Date.parse(a.createdAt) - Date.parse(b.createdAt),
	);
}

